 test(L"New Windows switches write and restore isolated registry preferences",[&]{
  auto prefix=L"Software\\HhubPrototype\\WritableSettingsTest-"+std::to_wstring(GetCurrentProcessId());auto path=report.parent_path()/L"writable-settings-undo.json";
  struct Cleanup{std::wstring prefix;std::filesystem::path path;~Cleanup(){RegDeleteTreeW(HKEY_CURRENT_USER,prefix.c_str());std::error_code error;std::filesystem::remove(path,error);}}cleanup{prefix,path};
  WindowsSettings settings(path,prefix);
  for(auto id:{L"capture",L"notifications",L"windowedOptimizations",L"gpuScheduling"}){
   auto before=settings.readOption(id).GetNamedArray(L"registryValues").Stringify();settings.set(id,true);ensure(flag(settings.readOption(id),L"enabled"));settings.restore(id);ensure(settings.readOption(id).GetNamedArray(L"registryValues").Stringify()==before);
   settings.set(id,false);ensure(!flag(settings.readOption(id),L"enabled"));settings.restore(id);ensure(settings.readOption(id).GetNamedArray(L"registryValues").Stringify()==before);
  }
  auto value=WindowsSettings::preferenceValues(L"windowedOptimizations")[0];std::wstring original=L"VRROptimizeEnable=1;OtherPreference=unchanged;SwapEffectUpgradeEnable=0;";
  settings.savePreference(value,WindowsSettings::storedValue(REG_SZ,original.c_str(),(original.size()+1)*sizeof(wchar_t)));auto before=settings.preferenceBackup(value).Stringify();settings.set(L"windowedOptimizations",true);
  auto bytes=WindowsSettings::preferenceBytes(settings.preferenceBackup(value));std::wstring changed((wchar_t*)bytes.data());ensure(changed==L"VRROptimizeEnable=1;OtherPreference=unchanged;SwapEffectUpgradeEnable=1;");settings.restore(L"windowedOptimizations");ensure(settings.preferenceBackup(value).Stringify()==before);
 });
 test(L"Shell tray accepts battery tooltip updates and restores the empty-data tip",[&]{
  WNDCLASSW wc{};wc.hInstance=GetModuleHandleW(nullptr);wc.lpfnWndProc=DefWindowProcW;wc.lpszClassName=L"Hhub.TrayTooltip.Test";RegisterClassW(&wc);
  auto owner=CreateWindowExW(0,wc.lpszClassName,L"",0,0,0,0,0,nullptr,nullptr,wc.hInstance,nullptr);ensure(owner!=nullptr);
  NOTIFYICONDATAW icon{sizeof(icon)};icon.hWnd=owner;icon.uID=99;icon.uFlags=NIF_ICON|NIF_TIP;icon.hIcon=LoadIconW(nullptr,IDI_APPLICATION);wcscpy_s(icon.szTip,L"H hub 1.0");
  struct Cleanup{NOTIFYICONDATAW* icon;~Cleanup(){Shell_NotifyIconW(NIM_DELETE,icon);DestroyWindow(icon->hWnd);}}cleanup{&icon};ensure(Shell_NotifyIconW(NIM_ADD,&icon));
  TrayBatteryTip tip(owner);auto data=object(LR"({"devices":[{"id":"mouse","name":"Rapoo Gaming Device","battery":69,"connected":true}]})");
  tip.update(icon,data);ensure(tip.nativeText==L"Rapoo Gaming Device：69%");
  auto device=data.GetNamedArray(L"devices").GetObjectAt(0);put(device,L"vid",9390.0);put(device,L"pid",5153.0);
  auto plugins=JsonArray::Parse(LR"([{"id":"hhub.developer-tools","installed":true,"deviceName":"Developer","hidTargets":[{"vid":9390,"pid":5153}]},{"id":"disabled","installed":true,"mode":"disabled","deviceName":"Disabled","hidTargets":[{"vid":9390,"pid":5153}]},{"id":"rapoo","installed":true,"name":"Plugin title","deviceName":"雷柏 VT3S MAX","hidTargets":[{"vid":9390,"pid":5153}]}])");
  tip.update(icon,data,plugins);ensure(tip.nativeText==L"雷柏 VT3S MAX：69%");
  put(device,L"pid",5154.0);tip.update(icon,data,plugins);ensure(tip.nativeText==L"Rapoo Gaming Device：69%");
  tip.update(icon,JsonObject{});ensure(tip.nativeText==L"H hub");
 });
