 test(L"Keyboard shortcut writes preserve all unrelated flags and filtering times",[&]{auto p=report.parent_path()/L"test-win-input-undo.json";WindowsSettings w(p);DWORD flags=FKF_FILTERKEYSON|FKF_HOTKEYACTIVE|FKF_CLICKON;w.spi=[&](UINT action,UINT,PVOID ptr,UINT){if(action==SPI_GETFILTERKEYS){auto s=(FILTERKEYS*)ptr;s->dwFlags=flags;s->iWaitMSec=123;s->iDelayMSec=456;s->iRepeatMSec=789;s->iBounceMSec=11;return TRUE;}if(action==SPI_SETFILTERKEYS){auto s=(FILTERKEYS*)ptr;ensure(s->iWaitMSec==123&&s->iDelayMSec==456&&s->iRepeatMSec==789&&s->iBounceMSec==11);flags=s->dwFlags;return TRUE;}return FALSE;};w.set(L"filterShortcut",false);ensure((flags&FKF_FILTERKEYSON)&&(flags&FKF_CLICKON)&&!(flags&FKF_HOTKEYACTIVE));w.restore(L"filterShortcut");ensure(flags==(FKF_FILTERKEYSON|FKF_HOTKEYACTIVE|FKF_CLICKON));std::filesystem::remove(p);});
