 test(L"Response estimates remain finite across supported rates",[&]{for(double rate:{40000.,44100.,48000.,96000.,192000.}){EqDsp response(rate);std::array<double,12> gains{};for(int step=0;step<100;step++){for(int i=0;i<12;i++)gains[i]=((step*17+i*7)%241-120)/10.;response.configure(gains,-3,true,true);ensure(std::isfinite(response.responseDb(1000)));}}});
 test(L"EQ invalid configuration is atomic and high bands respect Nyquist",[&]{EqDsp dsp(40000);std::array<double,12> bands{};bands[5]=6;dsp.configure(bands,-3,false,true);double before=dsp.responseDb(1000);auto centers=EqDsp::frequencies;centers[11]=20001;bool denied=false;try{dsp.configure(bands,-12,true,false,96,centers);}catch(std::invalid_argument const&){denied=true;}ensure(denied&&dsp.responseDb(1000)==before);auto c=EqDsp::peak(20000,12,40000);ensure(c.b0==1&&c.b1==0&&c.b2==0);for(double rate:{44100.,48000.,96000.,192000.})for(double f:{20.,31.25,1370.,16000.,20000.})for(double gain:{-12.,-6.,-.1,.1,6.,12.}){auto filter=EqDsp::peak(f,gain,rate);ensure(std::abs(20*std::log10(EqDsp::response(filter,f,rate))-gain)<.001);}});

 test(L"UI trend cache excludes raw sensor frames and preserves zero and unavailable readings",[&]{auto sample=object(LR"({"sampleTime":123,"cpu":0,"gpu":null,"memory":45})");JsonArray raw;for(int i=0;i<500;++i){JsonObject sensor;put(sensor,L"name",std::wstring(128,L'x'));raw.Append(sensor);}sample.SetNamedValue(L"sensors",raw);sample.SetNamedValue(L"disks",raw);auto snapshot=object(LR"({"fields":{"cpu":{"value":0},"gpu":{"value":null},"memory":{"value":45}}})");auto trend=HomeMonitoring::trendSample(sample,snapshot);ensure(!trend.HasKey(L"sensors")&&!trend.HasKey(L"disks"));ensure(num(trend,L"sampleTime")==123&&num(trend,L"cpu")==0&&num(trend,L"memory")==45);ensure(trend.GetNamedObject(L"homeFields").GetNamedObject(L"gpu").GetNamedValue(L"value").ValueType()==JsonValueType::Null);ensure(trend.Stringify().size()<512&&sample.GetNamedArray(L"sensors").Size()==500);});
