 test(L"Device configurations replace within one scene and remain independent across scenes",[&]{auto m=pluginFixtureModel();auto save=[&](std::wstring id){JsonObject p,d,b,req;put(p,L"id",id);put(p,L"name",id);put(p,L"device",std::wstring(L"mouse:one"));put(p,L"plugin",std::wstring(L"rapoo"));put(p,L"kind",std::wstring(L"mouse"));put(d,L"id",std::wstring(L"mouse:one"));put(d,L"name",std::wstring(L"Test Mouse"));b.SetNamedValue(L"profile",p);b.SetNamedValue(L"device",d);put(req,L"op",std::wstring(L"deviceProfileSave"));req.SetNamedValue(L"body",b);m.request(req);};save(L"one");save(L"two");auto bind=[&](std::wstring scene,std::wstring profile){JsonObject req,b;put(req,L"op",std::wstring(L"sceneBindProfile"));put(b,L"scene",scene);put(b,L"profile",profile);req.SetNamedValue(L"body",b);m.request(req);};bind(L"fps",L"one");bind(L"desktop",L"one");bind(L"fps",L"two");auto scenes=m.state.GetNamedArray(L"scenes");ensure(find(scenes,L"fps").GetNamedArray(L"bindings").Size()==1&&str(find(scenes,L"fps").GetNamedArray(L"bindings").GetObjectAt(0),L"profile")==L"two");ensure(str(find(scenes,L"desktop").GetNamedArray(L"bindings").GetObjectAt(0),L"profile")==L"one");m.request(object(LR"({"op":"deviceProfileDelete","body":{"id":"one"}})"));ensure(find(scenes,L"desktop").GetNamedArray(L"bindings").Size()==0&&find(scenes,L"fps").GetNamedArray(L"bindings").Size()==1);});
 test(L"Multiple foreground applications choose only the highest priority matching scene",[&]{auto m=pluginFixtureModel();auto scenes=m.state.GetNamedArray(L"scenes");auto fps=find(scenes,L"fps"),media=find(scenes,L"media");fps.SetNamedValue(L"apps",JsonArray::Parse(LR"(["C:\\Games\\Game.exe","C:\\Games\\Second.exe"])"));media.SetNamedValue(L"apps",JsonArray::Parse(LR"(["C:\\Games\\Second.exe"])"));put(fps,L"priority",10.0);put(media,L"priority",20.0);ensure(str(m.matchingScene(LR"(c:\games\second.exe)"),L"id")==L"media");put(media,L"priority",10.0);ensure(str(m.matchingScene(LR"(C:\Games\Second.exe)"),L"id")==L"fps");ensure(str(m.matchingScene(L"unmatched.exe"),L"id")==L"desktop");});
 test(L"Scene profile acknowledgements reject foreign plugins and stale requests",[&]{auto m=pluginFixtureModel();auto profile=object(LR"({"id":"ack-profile","name":"test","device":"mouse:one","plugin":"rapoo","kind":"mouse","revision":1,"payload":{}})");m.state.GetNamedArray(L"deviceProfiles").Append(profile);m.state.GetNamedArray(L"profileDevices").Append(object(LR"({"id":"mouse:one","name":"Test"})"));find(m.state.GetNamedArray(L"scenes"),L"desktop").GetNamedArray(L"bindings").Append(object(LR"({"device":"mouse:one","profile":"ack-profile"})"));m.requestSceneProfiles(find(m.state.GetNamedArray(L"scenes"),L"desktop"));auto old=m.state.GetNamedArray(L"profileRuntime").GetObjectAt(0);auto requestId=str(old,L"requestId");bool foreign=false,stale=false;try{m.sceneConfigurationRequest(L"deviceProfileCapture",object(LR"({"profile":"ack-profile","plugin":"rog","payload":{}})"));}catch(...){foreign=true;}put(profile,L"revision",2.0);m.requestSceneProfiles(find(m.state.GetNamedArray(L"scenes"),L"desktop"));JsonObject ack;put(ack,L"profile",std::wstring(L"ack-profile"));put(ack,L"plugin",std::wstring(L"rapoo"));put(ack,L"requestId",requestId);put(ack,L"confirmed",true);try{m.sceneConfigurationRequest(L"deviceProfileAck",ack);}catch(...){stale=true;}ensure(foreign&&stale);});

 test(L"Legacy named profiles refuse ambiguous receivers and foreign device containers",[&]{auto plugin=object(LR"({"hidTargets":[{"vid":9354,"pid":1}]})");auto device=object(LR"({"containerId":"one"})");auto detected=object(LR"({"devices":[{"vid":9354,"pid":1,"containerId":"one"}]})");validateLegacyProfileDevice(detected,device,plugin);detected.GetNamedArray(L"devices").Append(object(LR"({"vid":9354,"pid":1,"containerId":"two"})"));bool ambiguous=false,foreign=false;try{validateLegacyProfileDevice(detected,device,plugin);}catch(...){ambiguous=true;}detected.GetNamedArray(L"devices").RemoveAtEnd();put(device,L"containerId",std::wstring(L"other"));try{validateLegacyProfileDevice(detected,device,plugin);}catch(...){foreign=true;}ensure(ambiguous&&foreign);});
