 test(L"FxSound five effects each change actual stereo samples and remain finite",[&]{std::vector<float> input(48000*2);for(int n=0;n<48000;n++){input[n*2]=(float)(.035*std::sin(2*3.14159265358979323846*120*n/48000)+.012*std::sin(2*3.14159265358979323846*6000*n/48000));input[n*2+1]=(float)(.025*std::sin(2*3.14159265358979323846*180*n/48000)+.018*std::sin(2*3.14159265358979323846*4300*n/48000));}for(int effect=0;effect<5;effect++){FxSoundEffects fx;std::array<double,5> controls{};controls[effect]=7;fx.configure(controls,true);auto actual=input;for(size_t frame=0;frame<48000;frame+=480)fx.process(actual.data()+frame*2,480);double difference=0;for(size_t n=0;n<actual.size();n++){ensure(std::isfinite(actual[n]));difference+=std::abs(actual[n]-input[n]);}ensure(difference>.01);}});
