static int eqCaptureProbe(std::filesystem::path report){std::wstring text;HANDLE stop=CreateEventW(nullptr,TRUE,FALSE,nullptr),ready=CreateEventW(nullptr,FALSE,FALSE,nullptr);try{auto e=audioEnumerator();winrt::com_ptr<IMMDevice> d;check_hresult(e->GetDefaultAudioEndpoint(eRender,eMultimedia,d.put()));winrt::com_ptr<IAudioClient> render;check_hresult(d->Activate(__uuidof(IAudioClient),CLSCTX_ALL,nullptr,render.put_void()));WAVEFORMATEX format{};format.wFormatTag=WAVE_FORMAT_IEEE_FLOAT;format.nChannels=2;format.nSamplesPerSec=48000;format.wBitsPerSample=32;format.nBlockAlign=8;format.nAvgBytesPerSec=384000;check_hresult(render->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM|AUDCLNT_STREAMFLAGS_SRC_DEFAULT_QUALITY,200000,0,&format,nullptr));winrt::com_ptr<IAudioRenderClient> playback;check_hresult(render->GetService(__uuidof(IAudioRenderClient),playback.put_void()));UINT32 capacity{};render->GetBufferSize(&capacity);BYTE* buffer{};check_hresult(playback->GetBuffer(capacity,&buffer));check_hresult(playback->ReleaseBuffer(capacity,AUDCLNT_BUFFERFLAGS_SILENT));auto capture=processCapture(GetCurrentProcessId(),stop);WAVEFORMATEX pcm=format;pcm.wFormatTag=WAVE_FORMAT_PCM;pcm.wBitsPerSample=16;pcm.nBlockAlign=4;pcm.nAvgBytesPerSec=192000;check_hresult(capture->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_LOOPBACK|AUDCLNT_STREAMFLAGS_EVENTCALLBACK|AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM|AUDCLNT_STREAMFLAGS_SRC_DEFAULT_QUALITY,0,0,&pcm,nullptr));check_hresult(capture->SetEventHandle(ready));winrt::com_ptr<IAudioCaptureClient> recording;check_hresult(capture->GetService(__uuidof(IAudioCaptureClient),recording.put_void()));check_hresult(capture->Start());check_hresult(render->Start());uint64_t frames=0;auto deadline=GetTickCount64()+1500;while(GetTickCount64()<deadline){UINT32 padding{};render->GetCurrentPadding(&padding);if(capacity>padding){check_hresult(playback->GetBuffer(capacity-padding,&buffer));check_hresult(playback->ReleaseBuffer(capacity-padding,AUDCLNT_BUFFERFLAGS_SILENT));}WaitForSingleObject(ready,10);UINT32 packet{};check_hresult(recording->GetNextPacketSize(&packet));while(packet){UINT32 n{};DWORD flags{};check_hresult(recording->GetBuffer(&buffer,&n,&flags,nullptr,nullptr));frames+=n;check_hresult(recording->ReleaseBuffer(n));check_hresult(recording->GetNextPacketSize(&packet));}}capture->Stop();render->Stop();if(!frames)throw hresult_error(E_FAIL,L"No process audio frames arrived");text=L"PASS WASAPI process-loopback activation and 48 kHz PCM capture\nPASS Independent WASAPI shared render initialization\nPASS Own-process silent audio frames captured: "+std::to_wstring(frames)+L"\nNo other application's audio was captured and no routing preferences were changed.\n";write(report,text);CloseHandle(stop);CloseHandle(ready);return 0;}catch(hresult_error const& e){text=L"FAIL WASAPI probe: "+std::wstring(e.message())+L" HRESULT "+std::to_wstring(e.code().value)+L"\n";write(report,text);CloseHandle(stop);CloseHandle(ready);return 1;}}

static int eqMuteProbe(std::filesystem::path report){std::wstring text;HANDLE stop=CreateEventW(nullptr,TRUE,FALSE,nullptr),ready=CreateEventW(nullptr,FALSE,FALSE,nullptr);try{auto e=audioEnumerator();winrt::com_ptr<IMMDevice> d;check_hresult(e->GetDefaultAudioEndpoint(eRender,eMultimedia,d.put()));winrt::com_ptr<IAudioClient> render;check_hresult(d->Activate(__uuidof(IAudioClient),CLSCTX_ALL,nullptr,render.put_void()));WAVEFORMATEX format{};format.wFormatTag=WAVE_FORMAT_IEEE_FLOAT;format.nChannels=2;format.nSamplesPerSec=48000;format.wBitsPerSample=32;format.nBlockAlign=8;format.nAvgBytesPerSec=384000;check_hresult(render->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM|AUDCLNT_STREAMFLAGS_SRC_DEFAULT_QUALITY,200000,0,&format,nullptr));winrt::com_ptr<IAudioRenderClient> playback;check_hresult(render->GetService(__uuidof(IAudioRenderClient),playback.put_void()));winrt::com_ptr<ISimpleAudioVolume> volume;check_hresult(render->GetService(__uuidof(ISimpleAudioVolume),volume.put_void()));BOOL originalMute{};check_hresult(volume->GetMute(&originalMute));check_hresult(volume->SetMute(TRUE,nullptr));struct UndoMute{ISimpleAudioVolume* v;BOOL old;~UndoMute(){v->SetMute(old,nullptr);}}restoreMute{volume.get(),originalMute};UINT32 capacity{};render->GetBufferSize(&capacity);BYTE* buffer{};check_hresult(playback->GetBuffer(capacity,&buffer));check_hresult(playback->ReleaseBuffer(capacity,AUDCLNT_BUFFERFLAGS_SILENT));auto capture=processCapture(GetCurrentProcessId(),stop);WAVEFORMATEX pcm=format;pcm.wFormatTag=WAVE_FORMAT_PCM;pcm.wBitsPerSample=16;pcm.nBlockAlign=4;pcm.nAvgBytesPerSec=192000;check_hresult(capture->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_LOOPBACK|AUDCLNT_STREAMFLAGS_EVENTCALLBACK|AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM|AUDCLNT_STREAMFLAGS_SRC_DEFAULT_QUALITY,0,0,&pcm,nullptr));check_hresult(capture->SetEventHandle(ready));winrt::com_ptr<IAudioCaptureClient> recording;check_hresult(capture->GetService(__uuidof(IAudioCaptureClient),recording.put_void()));check_hresult(capture->Start());check_hresult(render->Start());uint64_t frames=0;double peak=0;uint64_t generated=0;auto deadline=GetTickCount64()+1500;while(GetTickCount64()<deadline){UINT32 padding{};render->GetCurrentPadding(&padding);if(capacity>padding){check_hresult(playback->GetBuffer(capacity-padding,&buffer));auto samples=(float*)buffer;for(UINT32 i=0;i<capacity-padding;i++){float sample=(float)(0.02*std::sin(2*3.14159265358979323846*1000*(generated++)/48000.0));samples[i*2]=sample;samples[i*2+1]=sample;}check_hresult(playback->ReleaseBuffer(capacity-padding,0));}WaitForSingleObject(ready,10);UINT32 packet{};check_hresult(recording->GetNextPacketSize(&packet));while(packet){UINT32 n{};DWORD flags{};check_hresult(recording->GetBuffer(&buffer,&n,&flags,nullptr,nullptr));frames+=n;if(!(flags&AUDCLNT_BUFFERFLAGS_SILENT)){auto samples=(int16_t*)buffer;for(UINT32 i=0;i<n*2;i++)peak=std::max(peak,std::abs(samples[i]/32768.0));}check_hresult(recording->ReleaseBuffer(n));check_hresult(recording->GetNextPacketSize(&packet));}}capture->Stop();render->Stop();if(!frames)throw hresult_error(E_FAIL,L"No process audio frames arrived");text=L"Own render session was muted before rendering the test tone. Original mute restored on exit.\nCaptured frames: "+std::to_wstring(frames)+L"\nCaptured peak while muted: "+std::to_wstring(peak)+L"\n";write(report,text);CloseHandle(stop);CloseHandle(ready);return 0;}catch(hresult_error const& e){text=L"FAIL WASAPI probe: "+std::wstring(e.message())+L" HRESULT "+std::to_wstring(e.code().value)+L"\n";write(report,text);CloseHandle(stop);CloseHandle(ready);return 1;}}

static int eqEndpointProbe(std::filesystem::path report){JsonObject result;JsonArray devices;auto e=audioEnumerator();HKEY key{};if(RegOpenKeyExW(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\MMDevices\\Audio\\Render",0,KEY_READ,&key)!=ERROR_SUCCESS)return 1;for(DWORD i=0;;i++){wchar_t name[256]{};DWORD length=256;if(RegEnumKeyExW(key,i,name,&length,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;auto id=std::wstring(L"{0.0.0.00000000}.")+name;JsonObject d;put(d,L"id",id);winrt::com_ptr<IMMDevice> endpoint;auto hr=e->GetDevice(id.c_str(),endpoint.put());put(d,L"getDevice",(double)hr);if(SUCCEEDED(hr)){put(d,L"name",audioName(endpoint.get()));winrt::com_ptr<IAudioClient> c;hr=endpoint->Activate(__uuidof(IAudioClient),CLSCTX_ALL,nullptr,c.put_void());put(d,L"activate",(double)hr);if(SUCCEEDED(hr)){WAVEFORMATEX* mix{};hr=c->GetMixFormat(&mix);put(d,L"mixFormat",(double)hr);if(mix){put(d,L"channels",(double)mix->nChannels);put(d,L"rate",(double)mix->nSamplesPerSec);CoTaskMemFree(mix);}}}devices.Append(d);}RegCloseKey(key);result.SetNamedValue(L"devices",devices);write(report,std::wstring(result.Stringify()));return 0;}

static int eqDefaults(std::filesystem::path file,bool restoring){try{auto enumerator=audioEnumerator();if(!restoring){JsonArray a;for(int flow=0;flow<2;flow++)for(int role=0;role<3;role++){winrt::com_ptr<IMMDevice> d;JsonObject item;put(item,L"flow",(double)flow);put(item,L"role",(double)role);if(SUCCEEDED(enumerator->GetDefaultAudioEndpoint((EDataFlow)flow,(ERole)role,d.put())))put(item,L"id",audioId(d.get()));else put(item,L"id",std::wstring());a.Append(item);}JsonObject backup;backup.SetNamedValue(L"defaults",a);write(file,std::wstring(backup.Stringify()));return 0;}auto backup=object(read(file));GUID clsid{};check_hresult(CLSIDFromString(L"{870AF99C-171D-4F9E-AF0D-E63DF40C2BC9}",&clsid));winrt::com_ptr<EqDefaultPolicy> policy;check_hresult(CoCreateInstance(clsid,nullptr,CLSCTX_ALL,__uuidof(EqDefaultPolicy),policy.put_void()));for(auto const& v:backup.GetNamedArray(L"defaults")){auto item=v.GetObject();auto id=str(item,L"id");if(id.empty())continue;int flow=(int)num(item,L"flow"),role=(int)num(item,L"role");if(flow<0||flow>1||role<0||role>2)throw hresult_invalid_argument();winrt::com_ptr<IMMDevice> original;check_hresult(enumerator->GetDevice(id.c_str(),original.put()));winrt::com_ptr<IMMDevice> current;if(SUCCEEDED(enumerator->GetDefaultAudioEndpoint((EDataFlow)flow,(ERole)role,current.put()))&&audioId(current.get())==id)continue;check_hresult(policy->SetDefaultEndpoint(id.c_str(),(ERole)role));}return 0;}catch(...){return 1;}}

